package com.jnapanam.sportszone.training.controller;import com.jnapanam.sportszone.training.dto.*;import com.jnapanam.sportszone.training.service.TrainingService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/coaching")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS','COACH')")public class CoachTrainingController{private final TrainingService s;public CoachTrainingController(TrainingService s){this.s=s;}@GetMapping("/batches/{id}/participants")public List<EnrollmentResponse>roster(@PathVariable UUID id){return s.roster(id);}@PutMapping("/enrollments/{id}/attendance")@ResponseStatus(HttpStatus.NO_CONTENT)public void attendance(@PathVariable UUID id,@Valid@RequestBody AttendanceRequest r){s.attendance(id,r);}}
